// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
// Einstellungen + Webhook-Parameter zusammenführen und validieren.
const cfg = {
  // ── aus der Data Table pw_config ──
  paperless_url:    pw('paperless_url'),
  absender:         pw('mail_absender'),
  empfaenger_email: pw('mail_betrieb'),

  // ── fachlich, hier zu pflegen ──
  // feld_projekt: Name des Paperless-Custom-Fields mit der Projektnummer.
  feld_projekt: 'Projektnummer'
};

// Der Aufrufparameter kommt aus dem Webhook, NICHT aus $input: dort liegen
// seit der Umstellung auf pw_config die Zeilen der Data Table.
const body = $('Webhook').first().json.body ?? {};
const projekt = String(body.projekt ?? '').trim();
if (!projekt) {
  throw new Error('Kein "projekt" im Webhook-Body. Erwartet z. B. {"projekt": "P-2026-017"}');
}

const empfaenger = String(body.empfaenger ?? '').trim() || cfg.empfaenger_email;
if (empfaenger.indexOf('@') === -1) throw new Error('Ungültige Empfänger-Adresse: ' + empfaenger);

const projekt_slug = projekt.replace(/[^\wäöüÄÖÜß.-]+/g, '_');

return [{ json: Object.assign({}, cfg, { projekt, projekt_slug, empfaenger }) }];

// Prüfen, ob das Projektnummer-Feld existiert, und die Abfrage bauen.
const cfg = $('Konfiguration').first().json;
const fields = $json.results || [];

const feld = fields.find(f => String(f.name).toLowerCase() === cfg.feld_projekt.toLowerCase());
if (!feld) {
  throw new Error('Custom Field "' + cfg.feld_projekt + '" existiert nicht in Paperless; bitte anlegen (Typ Text). Befüllt wird es automatisch vom Workflow felder-erkennen-mistral.');
}

const customFieldQuery = JSON.stringify([cfg.feld_projekt, 'exact', cfg.projekt]);

return [{ json: Object.assign({}, cfg, { projekt_feld_id: feld.id, customFieldQuery }) }];

// Pro Dokument: Download-URL (Original bei PDF/TIF/TIFF, sonst Archiv-PDF),
// eindeutigen ZIP-Dateinamen und Korrespondent-Namen für die CSV vorbereiten.
const cfg = $('Feld prüfen').first().json;
const docs = $('Dokumente laden').first().json.results || [];
const okExt = ['.pdf', '.tif', '.tiff'];

const korr = {};
($input.first().json.results || []).forEach(k => { korr[k.id] = k.name; });

return docs.map((d, i) => {
  const orig = d.original_file_name || '';
  const name = orig.toLowerCase();
  const useOriginal = okExt.some(ext => name.endsWith(ext));

  const dotPos = orig.lastIndexOf('.');
  const ext = (useOriginal && dotPos > 0) ? orig.slice(dotPos).toLowerCase() : '.pdf';
  let base = d.title || ('Dokument-' + d.id);
  base = base.replace(/[\\/:*?"<>|\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
  if (!base) base = 'Dokument-' + d.id;

  return { json: {
    nr: i + 1,
    id: d.id,
    title: d.title || ('Dokument ' + d.id),
    created: d.created,
    korrespondent: d.correspondent ? (korr[d.correspondent] || '') : '',
    original_file_name: orig || null,
    zip_name: String(i + 1).padStart(3, '0') + '_' + base + ext,
    download_url: cfg.paperless_url + '/api/documents/' + d.id + '/download/' + (useOriginal ? '?original=true' : '')
  }};
});

// Dateiname aus der Dokumentliste auf den Download übernehmen.
const doc = $('Dokumentliste aufbauen').item.json;
const item = $input.item;

if (!item.binary || !item.binary.data) {
  throw new Error('Kein Binärinhalt für Dokument ' + doc.id + ': Download fehlgeschlagen?');
}

item.binary.data.fileName = doc.zip_name;
return item;

// Alle heruntergeladenen Dokumente in EIN Item bündeln, damit der
// Compression-Node daraus ein einzelnes ZIP baut.
const items = $input.all();
if (!items.length) throw new Error('Keine Dokumente zum Packen vorhanden.');

const binary = {};
items.forEach((item, i) => {
  if (!item.binary || !item.binary.data) {
    throw new Error('Dokument ohne Binärdaten an Position ' + (i + 1) + ': Download fehlgeschlagen?');
  }
  binary['file_' + String(i).padStart(3, '0')] = item.binary.data;
});

return [{ json: { anzahl: items.length }, binary }];

// CSV-Dokumentliste erzeugen und als zweiten Anhang an das Item hängen.
// Semikolon-getrennt + BOM, damit deutsches Excel sie direkt sauber öffnet.
const cfg = $('Feld prüfen').first().json;
const docs = $('Dokumentliste aufbauen').all().map(i => i.json);

const esc = (v) => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const header = ['Nr', 'Paperless-ID', 'Titel', 'Datum', 'Korrespondent', 'Original-Dateiname', 'Datei im ZIP'].join(';');
const lines = docs.map(d => [
  d.nr,
  d.id,
  esc(d.title),
  d.created ? String(d.created).slice(0, 10) : '',
  esc(d.korrespondent),
  esc(d.original_file_name || ''),
  esc(d.zip_name)
].join(';'));
const csv = '\ufeff' + header + '\n' + lines.join('\n') + '\n';

const item = $input.first();
item.binary = item.binary || {};
item.binary.csv = await this.helpers.prepareBinaryData(
  Buffer.from(csv, 'utf8'),
  'Dokumentliste-' + cfg.projekt_slug + '.csv',
  'text/csv'
);
item.json.anzahl = docs.length;
return item;
